<div class="tp-grid tp-grid--3">
  <div class="tp-card tp-span-2">
    <div class="tp-card__head"><h3><?php echo icon('heart-pulse',18);?> <?php echo e(t('admin.health_checks'));?></h3><form method="post" action="/admin/health/cron"><?php echo csrf_field();?><button class="tp-btn tp-btn--primary tp-btn--sm" type="submit"><?php echo icon('play',14);?> <?php echo e(t('admin.run_cron'));?></button></form></div>
    <ul class="tp-status-list">
      <?php foreach($checks as $c){?><li><span><?php echo e($c['label']);?></span><span><span class="tp-text-3"><?php echo e($c['detail']);?></span> <span class="tp-badge tp-badge--<?php echo $c['ok']?'success':'warning';?>"><?php echo $c['ok']?'OK':'!';?></span></span></li><?php }?>
    </ul>
    <p class="tp-text-3 tp-mt-2"><?php echo e(t('admin.cron_hint'));?> <code>0 * * * * php <?php echo e(TP_ROOT);?>/cli/console.php cron</code></p>
