  <div class="tp-card"><h3><?php echo icon('file-text',18);?> <?php echo e(t('admin.logs'));?></h3><ul class="tp-status-list"><?php foreach($logs as $l){?><li><span class="tp-mono"><?php echo e($l['name']);?></span><span class="tp-text-3"><?php echo round($l['size']/1024);?> Ko · <?php echo e(date('d/m H:i',$l['mtime']));?></span></li><?php }if(!$logs){?><li class="tp-text-3"><?php echo e(t('common.nothing'));?></li><?php }?></ul></div>
</div>
<div class="tp-grid tp-grid--2 tp-mt-3">
  <div class="tp-card tp-card--table"><h3><?php echo e(t('admin.cron_runs'));?></h3><table class="tp-table tp-table--compact"><thead><tr><th><?php echo e(t('common.date'));?></th><th><?php echo e(t('admin.task'));?></th><th><?php echo e(t('common.status'));?></th><th><?php echo e(t('common.details'));?></th></tr></thead><tbody><?php foreach($runs as $r){?><tr><td class="tp-nowrap"><?php echo e(date_fmt($r['started_at'],'d/m H:i'));?></td><td><?php echo e($r['task']);?></td><td><span class="tp-badge tp-badge--<?php echo $r['status']==='ok'?'success':'danger';?>"><?php echo e($r['status']);?></span></td><td class="tp-text-3 tp-truncate"><?php echo e($r['output']);?></td></tr><?php }?></tbody></table></div>
  <div class="tp-card tp-card--table"><h3><?php echo e(t('admin.mail_log'));?> · <?php echo e(t('admin.health_queue'));?></h3><table class="tp-table tp-table--compact"><thead><tr><th><?php echo e(t('common.date'));?></th><th><?php echo e(t('admin.recipient'));?></th><th><?php echo e(t('field.subject'));?></th><th><?php echo e(t('common.status'));?></th></tr></thead><tbody><?php foreach($mails as $m){?><tr><td class="tp-nowrap"><?php echo e(date_fmt($m['created_at'],'d/m H:i'));?></td><td><?php echo e($m['to_email']);?></td><td class="tp-truncate"><?php echo e($m['subject']);?></td><td><span class="tp-badge tp-badge--<?php echo $m['status']==='sent'?'success':'danger';?>" title="<?php echo e($m['error']);?>"><?php echo e($m['status']);?></span></td></tr><?php }foreach($jobs as $j){?><tr><td class="tp-nowrap"><?php echo e(date_fmt($j['created_at'],'d/m H:i'));?></td><td colspan="2" class="tp-text-3">job #<?php echo(int)$j['id'];?> <?php echo e($j['queue']);?> · <?php echo(int)$j['attempts'];?> <?php echo e(t('admin.attempts'));?></td><td><span class="tp-badge tp-badge--<?php echo $j['failed_at']?'danger':'muted';?>"><?php echo $j['failed_at']?e(t('admin.failed')):e(t('admin.pending'));?></span></td></tr><?php }?></tbody></table></div>
</div>
